function stopBackfillPolling(){if(backfillPollTimer){clearTimeout(backfillPollTimer);backfillPollTimer=0;}}

async function request(path,{method="GET",body}={}){
  const response=await fetch(apiUrl(path),{method,credentials:"include",cache:"no-store",headers:body?{"Content-Type":"application/json"}:{},body:body?JSON.stringify(body):undefined});
  const data=await response.json().catch(()=>({}));
  if(!response.ok||!data.ok) throw new Error(errors[data.error]||data.error||"요청에 실패했습니다.");
  return data;
}

function rows(items,empty,render){return items?.length?items.map(render).join(""):`<p class="mileage-muted">${empty}</p>`;}
function numberInput(name,label,value,min=0){return `<label>${label}<input name="${name}" type="number" min="${min}" value="${Number(value||0)}"></label>`;}
function purchaseLimitText(item){const limit=Number(item.perUserLimit||0);if(!limit)return "";const period={lifetime:"전체 기간",weekly:"주간",monthly:"월간"}[item.purchaseLimitPeriod]||"전체 기간";return ` · ${period} ${limit}회 제한`;}
function stockText(item){return item.stock==null?"":`재고 ${Number(item.stock).toLocaleString()}개`;}
function productCopy(item){
  const scope=item.effectConfig?.scope||"all",role={top:"탑",jungle:"정글",mid:"미드",adc:"원딜",support:"서폿"}[scope];
  if(item.effectType==="stats_reset")return role?{short:`${role} 승/패·챔피언 승률 초기화 · 티어 유지`,detail:`사용 시 현재 시점을 기준으로 ${role} 표시 전적만 새로 집계됩니다. 다른 라인과 기존 경기 기록, 티어/MMR은 삭제되지 않습니다.`}:{short:"승/패·챔피언 승률 초기화 · 티어 유지",detail:"사용 시 현재 시점을 기준으로 표시 전적이 새로 집계됩니다. 기존 경기 기록과 티어/MMR은 삭제되지 않습니다."};
  if(item.effectType==="team_reroll")return{short:"현재 큐는 유지하고 팀 구성만 다시 편성합니다.",detail:"현재 큐의 참가자·포지션·경기 방식은 유지하고 Blue/Red 팀 구성만 다시 편성합니다."};
  return{short:item.shortDescription||item.description,detail:item.description};
}
const inventoryStatus=(status)=>({paid:"보유",processing:"사용 처리 중",fulfilled:"사용 완료",cancelled:"취소",refunded:"환불"}[status]||status);
function inventoryAction(item){
  if(item.inventoryStatus==="reserved")return`<b>사용 처리 중</b>`;
  const config=item.effectConfig||{};
  if(["coaching_full_discount","coaching_fixed_discount","service_ticket","discount_coupon"].includes(item.effectType)){
    const product=config.linkedCoachingProductId||(config.eligibleProductIds||[])[0];
    return product?`<a class="mileage-action" href="../?lesson=${encodeURIComponent(product)}&coupon=${encodeURIComponent(item.id)}">코칭 상품으로 이동</a>`:"<b>연결 상품 설정 필요</b>";
  }
  if(item.effectType==="stats_reset")return`<button class="mileage-action mileage-real-action" data-use-item="${esc(item.id)}" data-effect="stats_reset" data-scope="${esc(config.scope||"all")}">실제 사용하기</button>`;
  if(item.effectType==="team_reroll")return`<button class="mileage-action mileage-real-action" data-use-item="${esc(item.id)}" data-effect="team_reroll">실제 경기에서 사용</button>`;
  return "<b>보유 중</b>";
}

const transactionRows=(items)=>rows(items,"거래내역이 없습니다.",(t)=>`<div class="mileage-row"><span>${esc(labels[t.type]||t.type)}<br><small>${esc(t.reason)}</small></span><b class="${t.amount>0?"mileage-positive":"mileage-negative"}">${t.amount>0?"+":""}${Number(t.amount).toLocaleString()}P</b></div>`);
function capRow(label,value,limit){const current=Number(value||0),maximum=Number(limit||0),display=maximum?`${current.toLocaleString()} / ${maximum.toLocaleString()}P`:`${current.toLocaleString()}P · 상한 없음`;return`<div class="mileage-cap-row"><div><span>${esc(label)}</span><b>${display}</b></div>${maximum?`<progress max="${maximum}" value="${Math.min(current,maximum)}">${Math.round(current/maximum*100)}%</progress>`:""}</div>`;}
const questConditions={match_count:["판",1],win_count:["승",1],voice_seconds:["분",60],event_count:["회",1],duo_match_count:["판",1],newcomer_duo_match_count:["판",1]};
function questRow(q){const entries=Object.entries(q.conditions||{}).filter(([key,target])=>questConditions[key]&&Number(target)>0),parts=entries.map(([key,target])=>{const [unit,divisor]=questConditions[key],current=Math.floor(Number(q.progress?.[key]||0)/divisor),goal=Math.ceil(Number(target)/divisor);return{label:`${current.toLocaleString()} / ${goal.toLocaleString()}${unit}`,ratio:goal?current/goal:0};}),ratio=parts.length?Math.min(...parts.map(part=>part.ratio)):0,done=Boolean(q.completed),paid=Boolean(q.rewarded);return`<div class="mileage-quest-row ${done?"is-complete":""}"><div class="mileage-quest-head"><strong>${q.period==="daily"?"일일":"주간"} · ${esc(q.name)}</strong>${done?'<span class="mileage-complete-badge">✓ 완료</span>':""}</div><div class="mileage-quest-meta"><span>${esc(parts.map(part=>part.label).join(" · ")||"진행 조건 확인 중")}${done?paid?" · 지급 완료":" · 완료":""}</span><b>보상 ${Number(q.reward).toLocaleString()}P</b></div><progress max="100" value="${Math.min(100,Math.round(ratio*100))}">${Math.round(ratio*100)}%</progress></div>`;}
const backfillDate=(value)=>value?new Date(value).toLocaleString("ko-KR",{timeZone:"Asia/Seoul",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"}):"-";
const backfillRange=(job)=>({all:"전체 기록","30d":"최근 30일","90d":"최근 90일",custom:"직접 지정"}[job?.rangeConfig?.range]||"전체 기록");
function backfillStatus(job,notice=""){
  if(!job)return'<p class="mileage-muted">실행 기록이 없습니다.</p>';
  const done=Number(job.processedMatches||0),total=Number(job.totalMatches||0),percent=Number(job.progressPercent||0),preview=job.preview||{},skipped=Object.values(preview.skipped||{}).reduce((sum,value)=>sum+Number(value||0),0);
  const title={queued:"⏳ 작업 시작 대기...",running:`⏳ 실행 중 · ${done.toLocaleString()} / ${total.toLocaleString()}경기 · ${percent.toFixed(1)}%`,completed:"✅ 소급 지급 완료",failed:"❌ 소급 지급 실패"}[job.status]||esc(job.status);
  const timeLabel=job.status==="completed"?"완료 시각":job.status==="failed"?"실패 시각":"최근 갱신";
  return `${notice?`<p class="mileage-backfill-notice">${esc(notice)}</p>`:""}<div class="mileage-backfill-state"><strong>${title}</strong><progress max="100" value="${Math.max(0,Math.min(percent,100))}">${percent}%</progress><div class="mileage-backfill-details"><span>처리 경기 <b>${done.toLocaleString()} / ${total.toLocaleString()}</b></span><span>현재 지급 <b>${Number(job.actualPoints||0).toLocaleString()}P / 예상 ${Number(preview.newAmount||0).toLocaleString()}P</b></span><span>지급 유저 <b>${Number(job.actualUsers||0).toLocaleString()}명</b></span><span>제외 / 오류 <b>${skipped.toLocaleString()} / ${job.status==="failed"?1:0}</b></span><span>${timeLabel} <b>${backfillDate(job.completedAt||job.updatedAt)}</b></span></div>${job.error?`<p class="mileage-backfill-error">${esc(job.error)}</p><p class="mileage-muted">자동 재개 없음 · 관리자가 다시 미리보기 후 재시도할 수 있습니다.</p>`:""}</div>`;
}
function backfillHistory(jobs=[]){
  if(!jobs.length)return"";
  return `<details class="mileage-backfill-history"><summary>최근 작업 이력</summary>${jobs.slice(0,5).map(job=>`<div><span>${backfillDate(job.createdAt)} · ${backfillRange(job)}</span><b>${{queued:"대기",running:"실행 중",completed:"완료",failed:"실패"}[job.status]||esc(job.status)} · ${Number(job.processedMatches||0).toLocaleString()}경기 · ${Number(job.actualPoints||0).toLocaleString()}P</b></div>`).join("")}</details>`;
}
function pageNumbers(page,total){if(total<=7)return Array.from({length:total},(_,index)=>index+1);const values=[1,page-1,page,page+1,total].filter(value=>value>=1&&value<=total);return[...new Set(values)].sort((a,b)=>a-b);}
function pager(kind,meta={}){const page=Number(meta.page||1),total=Number(meta.totalPages||1);if(total<=1)return"";let previous=0;const numbers=pageNumbers(page,total).map(value=>{const gap=previous&&value-previous>1?'<span aria-hidden="true">…</span>':"";previous=value;return`${gap}<button type="button" data-${kind}-page="${value}" ${value===page?'aria-current="page"':""}>${value}</button>`;}).join("");return`<nav class="mileage-pagination" aria-label="페이지"><button type="button" data-${kind}-page="${page-1}" ${page<=1?"disabled":""}>이전</button>${numbers}<button type="button" data-${kind}-page="${page+1}" ${page>=total?"disabled":""}>다음</button></nav>`;}
const transactionPager=(meta)=>pager("transaction",meta);
function paintTransactions(root,wallet,guild){const meta=wallet.transactionPagination||{};transactionPage=Number(meta.page||1);const list=root.querySelector("#mileageRecentTransactions"),pager=root.querySelector("#mileageTransactionPager"),total=root.querySelector("#mileageTransactionTotal");if(list){list.innerHTML=transactionRows(wallet.transactions);list.removeAttribute("aria-busy");}if(total)total.textContent=Number(meta.total||0).toLocaleString();if(pager)pager.innerHTML=transactionPager(meta);bindTransactionPager(root,guild);}
function bindTransactionPager(root,guild){root.querySelectorAll("[data-transaction-page]").forEach(button=>button.addEventListener("click",async()=>{if(root.dataset.transactionLoading)return;root.dataset.transactionLoading="1";const page=Number(button.dataset.transactionPage||1),list=root.querySelector("#mileageRecentTransactions"),previous=list?.innerHTML||"";button.disabled=true;if(list){list.setAttribute("aria-busy","true");list.innerHTML='<p class="mileage-muted">불러오는 중...</p>';}try{const {wallet}=await request(`/api/mileage/guilds/${encodeURIComponent(guild.guildId)}/wallet?page=${page}&limit=5`);paintTransactions(root,wallet,guild);}catch(error){if(list){list.innerHTML=previous;list.removeAttribute("aria-busy");}button.disabled=false;alert(error.message);}finally{delete root.dataset.transactionLoading;}}));}

